def move_pdf_to_documents(apps, schema_editor):
    """Le PDF unique d'un guide devient son premier document."""
    Guide = apps.get_model("catalogue", "Guide")
    GuideDocument = apps.get_model("catalogue", "GuideDocument")
    for guide in Guide.objects.exclude(pdf=""):
        GuideDocument.objects.create(guide=guide, label="Guide (PDF)", file=guide.pdf.name, position=0)


